"""Verbatim SQL of Packages/Cards_New/cards_azericard (Unit18.dfm TDataMod_CARDS, SQL.Strings line lists).
Each dataset is kept as its TStrings line list (LINES_<name>) because Delphi edits lines by index (Clients SQL[25]); text() joins
them with CRLF like TStrings.Text. Generated by tools/gen_cards_sql.py from the .dfm, do not hand-edit."""


def text(lines, **repl):
    """TStrings.Text after SQL[i] := value assignments (repl keys are i<index>)."""
    L = list(lines)
    for k, v in repl.items():
        L[int(k[1:])] = v
    return "\r\n".join(L) + "\r\n"


